graphql.query:
query SignIn($auth: SignInInput!) {
  signIn(auth: $auth) {
    _id
    firstName
    lastName
    emailId
    token
    defaultAccount
    organisationId
  }
}

query OrgList {
  accounts {
    organisationId
    name
    isActive
    isAccepted
    isAdmin
  }
}

query ProjectList($params: ParamInput!) {
  projectOverview(params: $params) {
    _id
    name
    description
    active
    organisationId
    location { placeName lat lng }
    userCount { _id userCount }
    deviceCount { _id deviceCount }
    clusterCount { _id clusterCount }
    nonLoRaWANDeviceCount { _id nonLoRaWANDeviceCount }
  }
}

query DeviceList($params: ParamInput!) {
  projects(params: $params) {
    _id
    name
    clusters {
      _id
      name
      devices {
        _id
        name
        devEui
        hardwareId
        timestamp
      }
    }
  }
}

query DeviceDetails($params: ParamInput!) {
  projects(params: $params) {
    _id
    name
    clusters {
      _id
      name
      devices {
        _id
        name
        description
        devEui
        organisationId
        projectId
        clusterId
        hardwareId
        networkId
        hardwareType
        timestamp
        deleted
        position { placeName lat lng }
        outputs { outputId outputName value label color }
        attributes { attributeId attributeName value }
      }
    }
  }
}

query ModuleList($params: ParamInput!) {
  modules(params: $params) {
    _id
    label
    moduleType
    organisationId
  }
}

query HardwareList($params: ParamInput!) {
  hardwareList(params: $params) {
    _id
    organisationId
    name
    description
    tagId
    modelNo
    manufacturerId
    gpsSupported
    loRaWANConfiguration {
      controllers { moduleId code }
      profiles {
        _id
        name
        description
        downlinkInterfaces
      }
    }
    nonLoRaWANConfiguration {
      moduleId
      type
      dropdownOptions { option }
      dropdownType
      inputFieldType
      defaultValue
      required
      characterLimit
      isDefaultValue
      isCharacterLimit
    }
    type
    deleted
    emulatePDU
    jsonOutput
  }
}

query SendDownlink($action: SendDownlinkInput!) {
  sendDownlink(action: $action) {
    timestamp
    type
    message
  }
}
